import{_ as r,o,c as e,a2 as s}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"外観とテーマ","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/appearance.md","filePath":"ja-JP/user-guide/settings/appearance.md","lastUpdated":1787586465000}'),a={name:"ja-JP/user-guide/settings/appearance.md"};function n(i,t,l,g,d,h){return o(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="外観とテーマ" tabindex="-1">外観とテーマ <a class="header-anchor" href="#外観とテーマ" aria-label="Permalink to &quot;外観とテーマ&quot;">​</a></h1><p>Lertaro は、洗練されたモダンなデザインシステムを採用しており、柔軟なテーマモードの切り替えと豊富なカラーパレットを提供します。外観設定は、設定センターの左サイドバー下部（「バージョン情報」の上）に配置されています。</p><h2 id="_1-テーマモード-theme-modes" tabindex="-1">1. テーマモード（Theme Modes） <a class="header-anchor" href="#_1-テーマモード-theme-modes" aria-label="Permalink to &quot;1. テーマモード（Theme Modes）&quot;">​</a></h2><p>画面上部に表示される 3 つのモードカードから選択できます。</p><ul><li><strong>ライトモード（Light）</strong>：明るいデザインに固定します。下のテーマ一覧にはライトスタイルのテーマのみが表示されます。</li><li><strong>ダークモード（Dark）</strong>：落ち着いたダークデザインに固定します。下のテーマ一覧にはダークスタイルのテーマのみが表示されます。</li><li><strong>システムに追従（Follow System）</strong>：Windows のライト/ダーク設定に応じて自動で切り替わります。このモードでは下のグリッドが <strong>ライトテーマ</strong> と <strong>ダークテーマ</strong> の 2 つに分かれ、昼と夜でそれぞれお好みの配色を指定できます。Windows の設定変更に合わせて再起動なしでスムーズに切り替わります。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Lertaro はライトモードとダークモードで選択したテーマを個別に記憶するため、モードを切り替えても選択内容が失われることはありません。</p></div><h2 id="_2-テーマ選択カード" tabindex="-1">2. テーマ選択カード <a class="header-anchor" href="#_2-テーマ選択カード" aria-label="Permalink to &quot;2. テーマ選択カード&quot;">​</a></h2><p>テーマは実際の縮小プレビューカードで表示されます。検索ボックス、影、文字の視覚階層、選択ハイライトの配色が正確に再現されており、現在適用中のテーマにはチェックマークが付きます。</p><h3 id="標準・同梱テーマ一覧" tabindex="-1">標準・同梱テーマ一覧 <a class="header-anchor" href="#標準・同梱テーマ一覧" aria-label="Permalink to &quot;標準・同梱テーマ一覧&quot;">​</a></h3><ul><li><strong>コア内蔵テーマ（CoreExtensions）</strong>： <ul><li><strong>ライト（Light）</strong> / <strong>ダーク（Dark）</strong>：Windows のシステムスタイルに自然に溶け込むシンプルで洗練されたデザイン。</li><li><strong>ノルディックブルー（Nordic Blue）</strong>：深いネイビーとアイスブルーが調和したクールなギークスタイル。</li><li><strong>サクラピンク（Sakura Pink）</strong>：柔らかなパステルトーンの清潔感あるエレガントな配色。</li><li><strong>サイバーパンク（Cyberpunk）</strong>：ネオンイエローとミッドナイトパープルの高コントラストな近未来デザイン。</li></ul></li><li><strong>アニメテーマ（AnimeThemes、同梱）</strong>： <ul><li><strong>エヴァンゲリオン（Evangelion）</strong>、<strong>桜の開花（Sakura Blossom）</strong>、<strong>天気の子（Weathering with You）</strong>。</li></ul></li><li><strong>キュレーションテーマペア（Curated Themes、同梱）</strong>： <ul><li>ライト・ダークが対になった 10 組の配色：<strong>グレイシャーブルー（Glacier Blue）</strong>、<strong>テラコッタ（Terracotta）</strong>、<strong>フォレストグリーン（Forest Green）</strong>、<strong>アメジスト（Amethyst）</strong>、<strong>クリムゾン（Crimson）</strong>、<strong>グラファイト（Graphite）</strong>、<strong>インディゴナイト（Indigo Night）</strong>、<strong>ミントシアン（Mint Cyan）</strong>、<strong>シャンパンゴールド（Champagne Gold）</strong>、<strong>アンバーゴールド（Amber Gold）</strong>。</li></ul></li></ul><h3 id="プラグインによるテーマの拡張" tabindex="-1">プラグインによるテーマの拡張 <a class="header-anchor" href="#プラグインによるテーマの拡張" aria-label="Permalink to &quot;プラグインによるテーマの拡張&quot;">​</a></h3><p>すべてのテーマは <code>Lertaro.PluginSdk</code> の UI テーマ仕様に準拠しています。サードパーティ開発者は独自のテーマプラグインを作成して新しい配色を追加できます。</p>',12)])])}const p=r(a,[["render",n]]);export{c as __pageData,p as default};
